#!/usr/bin/env node
/**
 * The sitemap's Hindi half, checked against the files that actually exist.
 *
 *   node scripts/testSitemapHindi.js
 *
 * No network, no database, no server — buildSitemap() is pure once it is handed
 * a page set, which is why it takes one.
 *
 * WHAT THIS IS GUARDING. A sitemap is a CLAIM that these URLs are good. The
 * /hi/ pages are generated by aw/make-hindi-pages.js, which writes a page only
 * once its text is translated past a threshold — so the set changes as
 * translations land. Listing a Hindi URL that was never built means handing
 * Google a 404 and asking it to index it, and nothing else in the stack would
 * notice. Every negative check below is paired with a positive one, because a
 * sitemap that had silently stopped emitting Hindi entries altogether would
 * pass every "no bad URL" assertion on its own.
 */
const fs = require('fs');
const path = require('path');
const sitemap = require('../src/blogSitemap');

const WEBSITE_HI = path.resolve(__dirname, '../../astrowani-website/hi');

let pass = 0;
const failures = [];
function check(name, cond, detail) {
  if (cond) { pass++; return; }
  failures.push(detail ? `${name} — ${detail}` : name);
}

const locs = (xml) => [...xml.matchAll(/<loc>([^<]+)<\/loc>/g)].map((m) => m[1]);
const blocks = (xml) => xml.split('<url>').slice(1);

// ── 1. against the real directory ───────────────────────────────────────────
const real = sitemap.hindiPages();
const onDisk = fs.existsSync(WEBSITE_HI)
  ? new Set(fs.readdirSync(WEBSITE_HI).filter((f) => f.endsWith('.html')))
  : new Set();

check('hindiPages() reads the real directory', real.size === onDisk.size,
  `module ${real.size}, disk ${onDisk.size}`);
// THE POSITIVE CONTROL. Everything after this asserts "no bad Hindi URL", which
// an empty Hindi set would satisfy trivially.
check('there ARE Hindi pages to test', onDisk.size > 0, 'nothing in astrowani-website/hi');

const live = sitemap.buildSitemap([]);
const liveHi = locs(live).filter((u) => u.includes('/hi/'));
check('the live sitemap lists Hindi URLs', liveHi.length > 0);
for (const u of liveHi) {
  const file = u.split('/hi/')[1];
  check(`listed Hindi URL exists on disk: ${file}`, onDisk.has(file));
}

// ── 2. a page with no Hindi version must carry no alternates ────────────────
const enOnly = sitemap.buildSitemap([], new Set(['index.html']));
const enOnlyBlocks = blocks(enOnly);
const home = enOnlyBlocks.find((b) => b.includes('<loc>https://') && b.includes('xhtml:link'));
check('a translated page gets alternates', !!home);
const untranslated = enOnlyBlocks.filter((b) => !b.includes('xhtml:link'));
check('an untranslated page gets NO alternates', untranslated.length > 0,
  'every entry carried alternates, so the conditional is dead');
check('no /hi/ URL appears for an untranslated page',
  locs(enOnly).filter((u) => u.includes('/hi/')).length === 1,
  `got ${locs(enOnly).filter((u) => u.includes('/hi/')).join(', ')}`);

// ── 3. alternates are reciprocal ────────────────────────────────────────────
// Google ignores a one-sided hreflang set wholesale rather than half-honouring
// it, so the English and Hindi entries for one page must name the SAME pair.
const pair = blocks(sitemap.buildSitemap([], new Set(['marriage.html'])))
  .filter((b) => b.includes('marriage.html'));
check('both sides of a translated page are listed', pair.length === 2, `got ${pair.length}`);
if (pair.length === 2) {
  const alts = (b) => [...b.matchAll(/hreflang="([^"]+)" href="([^"]+)"/g)]
    .map((m) => `${m[1]} ${m[2]}`).sort().join(' | ');
  check('the two entries carry identical alternates', alts(pair[0]) === alts(pair[1]),
    `${alts(pair[0])}  vs  ${alts(pair[1])}`);
  // x-default is EXCLUDED here on purpose. It points at the English page, so a
  // plain "does this entry's loc appear as some href" test passes for the
  // English entry even with the en-IN alternate deleted — verified: that exact
  // regression slipped through the first version of this check. Every language
  // must be present AS A LANGUAGE.
  const langs = (b) => [...b.matchAll(/hreflang="([^"]+)" href="([^"]+)"/g)]
    .filter((m) => m[1] !== 'x-default');
  check('both languages are named, as languages',
    pair.every((b) => {
      const got = langs(b).map((m) => m[1]).sort().join(',');
      return got === 'en-IN,hi-IN';
    }), pair.map((b) => langs(b).map((m) => m[1]).join('+')).join(' vs '));
  check('each entry names itself among the LANGUAGE alternates',
    pair.every((b) => {
      const loc = b.match(/<loc>([^<]+)<\/loc>/)[1];
      return langs(b).some((m) => m[2] === loc);
    }), 'a self-referential hreflang is required');
  check('x-default points at the English page',
    pair[0].includes('hreflang="x-default" href="https://shop.astrowani.com/test-site/marriage.html"'));
}

// ── 4. fails closed ─────────────────────────────────────────────────────────
const none = sitemap.buildSitemap([], new Set());
check('with no Hindi pages, no /hi/ URL is emitted',
  locs(none).filter((u) => u.includes('/hi/')).length === 0);
check('…and the English sitemap is intact',
  locs(none).length === sitemap.STATIC_PAGES.length, `${locs(none).length} URLs`);
check('…and it is still a valid urlset', none.includes('<urlset') && none.includes('</urlset>'));

// ── 5. the namespace the alternates need ────────────────────────────────────
// Without it the xhtml:link elements are not valid XML and the whole file is
// rejected — one missing attribute costs every URL in it, not just the alternates.
check('the xhtml namespace is declared', live.includes('xmlns:xhtml="http://www.w3.org/1999/xhtml"'));
check('alternates sit INSIDE <url>', !/<\/url>\s*<xhtml:link/.test(live));

// ── 6. articles are unaffected ──────────────────────────────────────────────
const withPost = sitemap.buildSitemap([
  { slug: 'a-real-post', created_at: '2026-10-01T00:00:00Z', updated_at: '2026-10-02T00:00:00Z' },
  { slug: null, created_at: '2026-10-01T00:00:00Z' },
]);
check('a slugged article is still listed', locs(withPost).some((u) => u.includes('a-real-post')));
check('a slugless article is still skipped', !withPost.includes('id='));

// ── 7. articles in Hindi ────────────────────────────────────────────────────
// hasHindi is set by the route from a second query; buildSitemap only reads it.
const arts = sitemap.buildSitemap([
  { slug: 'translated', created_at: '2026-10-01T00:00:00Z', hasHindi: true },
  { slug: 'english-only', created_at: '2026-10-01T00:00:00Z', hasHindi: false },
], new Set());
const artLocs = locs(arts);
check('a translated article gets a Hindi URL',
  artLocs.includes('https://shop.astrowani.com/test-site/hi/blog-post.html?slug=translated'));
// THE ONE THAT MATTERS. An untranslated article listed under hreflang="hi-IN"
// serves the English body at a Hindi URL — a duplicate, not a translation.
check('an English-only article gets NO Hindi URL',
  !artLocs.some((u) => u.includes('hi/blog-post.html?slug=english-only')));
check('…and no alternates either',
  !blocks(arts).find((b) => b.includes('slug=english-only')).includes('xhtml:link'));
check('the article slug is URL-encoded in the Hindi loc',
  locs(sitemap.buildSitemap([{ slug: 'a b&c', created_at: '2026-10-01T00:00:00Z', hasHindi: true }], new Set()))
    .some((u) => u.includes('hi/blog-post.html?slug=a%20b%26c')));

console.log(`\n${pass} passed, ${failures.length} failed`);
for (const f of failures) console.log(`  FAIL  ${f}`);
process.exit(failures.length ? 1 : 0);
